import{_ as e,c as a,o as r,a7 as o}from"./chunks/framework.DLVsJyUe.js";const i="/ruidu-docs/images/orbitcontrol/user-guide/executions-page-list.png",d="/ruidu-docs/images/orbitcontrol/user-guide/executions-page-detail.png",s="/ruidu-docs/images/orbitcontrol/user-guide/executions-page-playback.gif",_=JSON.parse('{"title":"运行日志","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/executions.md","filePath":"orbitcontrol/user-guide/executions.md"}'),l={name:"orbitcontrol/user-guide/executions.md"};function n(c,t,h,u,p,g){return r(),a("div",null,t[0]||(t[0]=[o('<h1 id="运行日志" tabindex="-1">运行日志 <a class="header-anchor" href="#运行日志" aria-label="Permalink to &quot;运行日志&quot;">​</a></h1><p>「运行日志」记录每一次任务执行的完整信息：谁在何时执行了什么任务、运行数据如何、产出了哪些文件。无论任务是手动执行、<a href="./schedules.html">计划</a>调度还是<a href="./flows.html">自动化流程</a>触发，都会记录在这里。</p><h2 id="日志列表" tabindex="-1">日志列表 <a class="header-anchor" href="#日志列表" aria-label="Permalink to &quot;日志列表&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>列表以表格展示，支持按任务名称搜索、按站点筛选和分页：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>任务名称</td><td>执行时的任务名快照</td></tr><tr><td>设备名称</td><td>执行设备名快照</td></tr><tr><td>站点</td><td>所属站点</td></tr><tr><td>运行时间</td><td>计划/触发的时间</td></tr><tr><td>结束时间</td><td>实际完成时间</td></tr><tr><td>附件上传</td><td>媒体文件上传进度（已传/总数）</td></tr></tbody></table><p>点击任意一行进入<strong>执行详情</strong>。</p><h2 id="执行详情" tabindex="-1">执行详情 <a class="header-anchor" href="#执行详情" aria-label="Permalink to &quot;执行详情&quot;">​</a></h2><p>详情页分为三个页签：</p><p><img src="'+d+'" alt=""></p><h3 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h3><p>执行结果摘要，包括：</p><ul><li><strong>运行统计</strong>：执行时长、航点进度等</li><li><strong>电池/电量</strong>：执行期间电量变化</li><li><strong>设备信息</strong>：执行设备的信息</li><li><strong>任务概要</strong>：任务配置快照</li></ul><h3 id="回放" tabindex="-1">回放 <a class="header-anchor" href="#回放" aria-label="Permalink to &quot;回放&quot;">​</a></h3><p>执行期间设备记录的数据包（MCAP），加载后可逐帧回放设备运行过程。该执行未生成 MCAP 文件时会提示。</p><p><img src="'+s+'" alt=""></p><h3 id="媒体文件" tabindex="-1">媒体文件 <a class="header-anchor" href="#媒体文件" aria-label="Permalink to &quot;媒体文件&quot;">​</a></h3><p>执行期间设备拍摄的照片和录像，上传完成后集中展示。相关媒体也可在 <a href="./gallery.html">画廊</a> 中浏览。</p>',18)]))}const b=e(l,[["render",n]]);export{_ as __pageData,b as default};
